using System.Windows; using System.Windows.Controls; namespace CloudClient; public sealed class ShareDialog:Window { readonly ComboBox users=new(); readonly CheckBox write=new(){Content="Lesen & Schreiben erlauben"}; public MainWindow.UserItem? SelectedUser=>users.SelectedItem as MainWindow.UserItem; public bool CanWrite=>write.IsChecked==true; public ShareDialog(IEnumerable<MainWindow.UserItem> items){Title="Freigeben";Width=430;Height=260;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.NoResize;var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(new TextBlock{Text="Für Benutzer freigeben",FontSize=21,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,18)});users.ItemsSource=items;users.SelectedIndex=0;users.Height=36;p.Children.Add(users);write.Margin=new Thickness(0,18,0,18);p.Children.Add(write);var b=new Button{Content="Freigeben",Height=38};b.Click+=(_,__)=>{if(SelectedUser!=null)DialogResult=true;};p.Children.Add(b);Content=p;} }